void qr_selftest_render(uint8_t which, uint8_t * p_gray,
                        uint16_t w, uint16_t h)
{
    if ((which >= QR_SELFTEST_COUNT) || (NULL == p_gray) ||
        (0U == w) || (0U == h))
    {
        return;
    }

    const qr_selftest_t * p_selftest = &s_selftests[which];
    uint16_t const n = p_selftest->n;
    const uint8_t * p_m = p_selftest->p_data;

    /* white background (slightly off-white like the camera) */
    memset(p_gray, 235, (size_t) w * h);

    /* module size: the matrix already contains the 4-module quiet
     * zone, so the QR body spans n modules of min(w,h)/n px */
    uint16_t module = (h < w) ? h : w;
    module = (uint16_t) (module / n);
    if (module < 2U)
    {
        module = 2U;
    }

    int const x0 = ((int) w - (int) (n * module)) / 2;
    int const y0 = ((int) h - (int) (n * module)) / 2;

    for (uint16_t ry = 0U; ry < n; ry++)
    {
        for (uint16_t rx = 0U; rx < n; rx++)
        {
            if (0U == p_m[(size_t) ry * n + rx])
            {
                continue;    /* white module */
            }
            int const px = x0 + (int) (rx * module);
            int const py = y0 + (int) (ry * module);
            for (uint16_t dy = 0U; dy < module; dy++)
            {
                int const yy = py + (int) dy;
                if ((yy < 0) || (yy >= (int) h))
                {
                    continue;
                }
                uint8_t * p_row = p_gray + (size_t) yy * w;
                for (uint16_t dx = 0U; dx < module; dx++)
                {
                    int const xx = px + (int) dx;
                    if ((xx < 0) || (xx >= (int) w))
                    {
                        continue;
                    }
                    p_row[xx] = 0U;
                }
            }
        }
    }
}
